.neon-box {
  width: 100px;
  height: 100px;
  border: 2px solid #a855f7;
  border-radius: 12px;
  animation: neonPulse 2s ease-in-out infinite;
}
@keyframes neonPulse {
  0%, 100% {
    box-shadow:
      0 0 5px #a855f7,
      0 0 20px #a855f7,
      0 0 40px #7c3aed;
  }
  50% {
    box-shadow:
      0 0 10px #a855f7,
      0 0 40px #a855f7,
      0 0 80px #7c3aed,
      0 0 120px #7c3aed;
  }
}

